RSpec.describe "Owner-aware reads across owner states", type: :request do
  include_context "timekeeping contract fakes"

  let(:company) { create(:company) }
  let(:user) { create(:user, current_workspace_id: company.id) }
  let(:project) { create(:project, billable: true, client: create(:client, company:)) }
  let(:work_date) { Date.current.iso8601 }
  let(:read_paths) { [api_v1_timesheet_entry_index_path, api_v1_time_tracking_index_path] }

  before do
    create(:employment, company:, user:)
    user.add_role :admin, company
    create(:project_member, user:, project:)
    allow(Timekeeping::EntryApiClient).to receive(:new)
      .and_return(TimekeepingContract::FakeEntryApiClient.new(timekeeping: fake_timekeeping))
    sign_in user
  end

  def owner_reads_listed_entry(path, entry_id)
    send_request :get, path, params: { from: work_date, to: work_date }, headers: auth_headers(user)
    expect(response).to have_http_status(:ok)
    json_response.fetch("entries").fetch(work_date, []).find { |entry| entry["id"] == entry_id }
  end

  def owner_reads_create_legacy_entry
    send_request :post, api_v1_timesheet_entry_index_path, params: {
      project_id: project.id, user_id: user.id,
      timesheet_entry: { duration: 20, work_date:, note: "Legacy entry", bill_status: :unbilled }
    }, headers: auth_headers(user)
    expect(response).to be_successful
    json_response.fetch("entry").fetch("id")
  end

  def owner_reads_create_timekeeping_entry
    TimekeepingOwnership.current.update!(owner: "timekeeping", generation: 2, handoff_step: nil)
    fake_timekeeping.add_entry(company_id: company.id, user_id: user.id, project_id: project.id,
                               work_date:, duration: 45.0, note: "Timekeeping entry").fetch("id")
  end

  def owner_reads_create_prepared_entry
    TimekeepingOwnership.current.update!(owner: "monolith", generation: 3, monolith_store: "prepared", handoff_step: nil)
    ActiveRecord::Base.connection.select_value(ActiveRecord::Base.sanitize_sql_array([
      "INSERT INTO entries (company_id, user_id, project_id, work_date, duration, note, bill_status, created_at, updated_at) " \
      "VALUES (?, ?, ?, ?, 60.0, 'Prepared entry', 'unbilled', NOW(), NOW()) RETURNING id",
      company.id, user.id, project.id, work_date
    ]))
  end

  def owner_reads_shape(entry)
    entry.transform_values { |value| value.class.name }
  end

  it "shows an entry created through the legacy route in both reads" do
    entry_id = owner_reads_create_legacy_entry

    expect(TimesheetEntry.where(id: entry_id)).to exist
    read_paths.each do |path|
      expect([path, owner_reads_listed_entry(path, entry_id)&.fetch("note")]).to eq([path, "Legacy entry"])
    end
  end

  it "shows a prepared-store entry in both reads while timesheet_entries has no row for it" do
    entry_id = owner_reads_create_prepared_entry

    read_paths.each do |path|
      expect([path, owner_reads_listed_entry(path, entry_id)&.fetch("note")]).to eq([path, "Prepared entry"])
    end
    expect(TimesheetEntry.unscoped.where(id: entry_id)).not_to exist
  end

  it "renders the same entry keys and value types in the legacy, prepared and Timekeeping states" do
    legacy_id = owner_reads_create_legacy_entry
    legacy = owner_reads_listed_entry(api_v1_timesheet_entry_index_path, legacy_id)

    prepared_id = owner_reads_create_prepared_entry
    prepared = owner_reads_listed_entry(api_v1_timesheet_entry_index_path, prepared_id)

    timekeeping_id = owner_reads_create_timekeeping_entry
    timekeeping = owner_reads_listed_entry(api_v1_timesheet_entry_index_path, timekeeping_id)

    expect(legacy).to be_present
    expect(owner_reads_shape(prepared)).to eq(owner_reads_shape(legacy))
    expect(owner_reads_shape(timekeeping)).to eq(owner_reads_shape(legacy))
  end
end
